// supersedes the prior, so consumers should overwrite (not sum) on receipt.
// Adapters that only receive aggregate shutdown totals should emit at most one
// final Tokens event rather than inventing deltas.
type Tokens struct {
	In  int
	Out int
}

func (Tokens) isEvent() {}

